// src/components/common/TransactionForm.jsx
import React from 'react';
import './TransactionForm.css';

const TransactionForm = ({ 
  title, 
  isCare,       // if true, show only amount field
  txData, 
  onChange, 
  onSubmit, 
  onCancel,
  representative
}) => {
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    onChange({ target: { name, value } });
  };

  return (
    <div className="claim-card transaction-container">
      <div className="transaction-title">{title}</div>
      <div className="tx-form">
        {/* Amount field - always shown */}
        <div className="field">
          <label>Transaction Amount *</label>
          <input
            type="text"
            name="amount"
            value={txData.amount || ''}
            onChange={handleInputChange}
            placeholder="e.g., 150000"
            required
          />
        </div>

        {!isCare && (
          <>
            {/* Transaction ID - only for non-care */}
            <div className="field">
              <label>Transaction ID *</label>
              <input
                type="text"
                name="txId"
                value={txData.txId || ''}
                onChange={handleInputChange}
                placeholder="e.g., MP260610.2000.X08195"
                required
              />
            </div>

            {/* Transaction Date - only for non-care */}
            <div className="field">
              <label>Transaction Date</label>
              <input
                type="text"
                name="date"
                value={txData.date || ''}
                readOnly
                className="readonly"
              />
            </div>

            {/* Representative - only for non-care */}
            <div className="field">
              <label>Representative</label>
              <input
                type="text"
                value={representative || 'Shabani'}
                disabled
                className="readonly"
              />
            </div>
          </>
        )}
        
        <div className="form-actions">
          <button type="button" className="btn-outline" onClick={onCancel}>Cancel</button>
          <button 
            type="button" 
            className="submit-btn" 
            onClick={onSubmit}
            disabled={!txData.amount || parseFloat(txData.amount) <= 0}
          >
            <i className="fas fa-check"></i> Submit
          </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionForm;
